begin;
set local search_path = public, extensions;
create extension if not exists pgtap with schema extensions;
select extensions.plan(25);
select extensions.ok(not has_function_privilege('anon','public.plannix_auth_check_orphan_generation(jsonb)','execute'),'browser cannot classify');
select extensions.ok(not has_function_privilege('authenticated','public.plannix_auth_reset_orphan_generation(jsonb,text,timestamp with time zone)','execute'),'browser cannot retire');
select extensions.ok(has_function_privilege('service_role','public.plannix_auth_reset_orphan_generation(jsonb,text,timestamp with time zone)','execute'),'service may reset');
select extensions.ok(not has_table_privilege('service_role','private.plannix_auth_used_reset_proofs','select,insert,update,delete'),'proof ledger private');
select extensions.ok((select relrowsecurity from pg_class where oid='private.plannix_auth_used_reset_proofs'::regclass),'proof ledger RLS');
create temporary table reset_context as select nextval('private.plannix_auth_generation_seq') as generation, clock_timestamp()+interval '1 minute' expiry;
create temporary table reset_candidate as select jsonb_build_object('markers','[]'::jsonb,'sessions',jsonb_build_array(jsonb_build_object('name','__Host-plannix-s-'||generation,'hash',repeat('a',64)))) c from reset_context;
create temporary table reset_result as select public.plannix_auth_check_orphan_generation((select c from reset_candidate))->>'state' outcome;
set local search_path = public, extensions;
select extensions.is((select outcome from reset_result),'eligible','classifier eligible');
select extensions.is((select count(*) from private.plannix_auth_retired_generations where generation=(select generation from reset_context)),0::bigint,'offer does not retire');
update reset_result set outcome=public.plannix_auth_reset_orphan_generation((select c from reset_candidate),repeat('3',64),clock_timestamp()-interval '1 second')->>'state';
set local search_path = public, extensions;
select extensions.is((select outcome from reset_result),'ineligible','expired proof denied');
set local synchronous_commit='off';
select extensions.ok((public.plannix_auth_browser_reset_preflight()->>'synchronousCommitEnabled')::boolean=false,'preflight rejects asynchronous durability');
update reset_result set outcome=public.plannix_auth_reset_orphan_generation((select c from reset_candidate),repeat('3',64),(select expiry from reset_context))->>'state';
set local search_path = public, extensions;
select extensions.is((select outcome from reset_result),'retired','reset succeeds');
select extensions.is(current_setting('synchronous_commit'),'on','retirement forces synchronous commit through transaction end');
update reset_result set outcome=public.plannix_auth_reset_orphan_generation((select c from reset_candidate),repeat('3',64),(select expiry from reset_context))->>'state';
set local search_path = public, extensions;
select extensions.is((select outcome from reset_result),'ineligible','replay denied');
select extensions.is((select count(*) from private.plannix_auth_retired_generations where generation=(select generation from reset_context)),1::bigint,'retirement retained');
select extensions.is(current_setting('transaction_timeout'),'1s','transaction timer persists outside function');

select extensions.ok(not has_function_privilege('anon','public.plannix_auth_confirm_orphan_reset(jsonb,text,timestamp with time zone)','execute'),'anon cannot confirm');
select extensions.ok(not has_function_privilege('authenticated','public.plannix_auth_confirm_orphan_reset(jsonb,text,timestamp with time zone)','execute'),'authenticated cannot confirm');
select extensions.ok(has_function_privilege('service_role','public.plannix_auth_confirm_orphan_reset(jsonb,text,timestamp with time zone)','execute'),'service can confirm');
select extensions.ok(not has_function_privilege('anon','public.plannix_auth_browser_reset_preflight()','execute'),'preflight service only');
select extensions.is(public.plannix_auth_confirm_orphan_reset((select c from reset_candidate),repeat('3',64),(select expiry from reset_context))->>'state','confirmed','both matching records confirm');
select extensions.is(public.plannix_auth_confirm_orphan_reset((select c from reset_candidate),repeat('4',64),(select expiry from reset_context))->>'state','unconfirmed','wrong proof cannot confirm');
select extensions.is(public.plannix_auth_confirm_orphan_reset(jsonb_set((select c from reset_candidate),'{sessions,0,hash}',to_jsonb(repeat('b',64))),repeat('3',64),(select expiry from reset_context))->>'state','unconfirmed','changed cookie secret cannot confirm');
select extensions.is(public.plannix_auth_confirm_orphan_reset((select c from reset_candidate),repeat('3',64),(select expiry+interval '1 second' from reset_context))->>'state','unconfirmed','changed proof expiry cannot confirm');
select extensions.is(public.plannix_auth_confirm_orphan_reset(jsonb_set((select c from reset_candidate),'{sessions,0,name}',to_jsonb('__Host-plannix-s-999999'::text)),repeat('3',64),(select expiry from reset_context))->>'state','unconfirmed','changed generation cannot confirm');
delete from private.plannix_auth_retired_generations where generation=(select generation from reset_context);
select extensions.is(public.plannix_auth_confirm_orphan_reset((select c from reset_candidate),repeat('3',64),(select expiry from reset_context))->>'state','unconfirmed','proof without retirement cannot confirm');
delete from private.plannix_auth_used_reset_proofs where proof_hash=repeat('3',64);
select extensions.is(public.plannix_auth_confirm_orphan_reset((select c from reset_candidate),repeat('3',64),(select expiry from reset_context))->>'state','unconfirmed','missing records cannot confirm');
select * from extensions.finish();
rollback;
